<script setup lang="ts">definePageMeta({ middleware: 'auth' }); const route = useRoute(); const { find } = useCourses(); const { data: course } = await useAsyncData(`course-${route.params.id}`, () => find(Number(route.params.id))); if (!course.value) throw createError({ statusCode: 404 })</script>
<template><div v-if="course" class="page-shell"><PageHeader :title="course.course_code" :description="course.course_title"><template #actions><StatusBadge :status="course.status" /><BaseButton :to="`/courses/${course.id}/edit`">Edit course</BaseButton></template></PageHeader><BaseCard><dl class="grid gap-5 sm:grid-cols-3"><div><dt class="text-sm text-slate-500">Course code</dt><dd class="mt-1 font-semibold">{{ course.course_code }}</dd></div><div><dt class="text-sm text-slate-500">Units</dt><dd class="mt-1 font-semibold">{{ course.units }}</dd></div><div><dt class="text-sm text-slate-500">Status</dt><dd class="mt-1"><StatusBadge :status="course.status" /></dd></div></dl></BaseCard></div></template>
